#!/usr/bin/env node
// Runs exactly one test for the Lore test-command interface. The selector is
// "<repo-relative-file>::<full test name>" as emitted by lore-list-tests.mjs.
// Jest's -t flag is a regex matched against the full name, so the name is
// escaped and anchored - a name containing (parens) or {500} must match
// literally - and the file is passed with --runTestsByPath, which takes a path
// rather than the regex a bare positional argument would be.
// A selector that matches nothing is a failure, never a silently green run of
// an empty suite.
import {execFileSync} from 'node:child_process';
import {readFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import process from 'node:process';

const selector = process.argv[2];

if (!selector || !selector.includes('::')) {
  process.stderr.write('usage: lore-run-test.mjs "<file>::<full test name>"\n');
  process.exit(2);
}

const separator = selector.indexOf('::');
const file = selector.slice(0, separator);
const name = selector.slice(separator + 2);
const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const reportFile = join(tmpdir(), `hal-engine-jest-run-${process.pid}.json`);

let runFailed = false;

try {
  execFileSync(
    'npx',
    [
      'jest',
      '--runTestsByPath',
      file,
      '-t',
      `^${escaped}$`,
      '--json',
      `--outputFile=${reportFile}`,
      '--coverage',
      '--coverageReporters=lcov',
    ],
    {
      cwd: process.cwd(),
      stdio: ['ignore', 'inherit', 'inherit'],
      // The suite runs as ESM; jest needs the flag in every spawn, not just npm test.
      env: {...process.env, NODE_OPTIONS: `${process.env.NODE_OPTIONS ?? ''} --experimental-vm-modules`.trim()},
    }
  );
} catch {
  runFailed = true;
}

let report;

try {
  report = JSON.parse(readFileSync(reportFile, 'utf8'));
} catch (error) {
  process.stderr.write(`jest produced no readable report at ${reportFile}: ${error.message}\n`);
  process.exit(1);
} finally {
  rmSync(reportFile, {force: true});
}

// Every test in the file that -t did not select is reported as pending, so the
// count that matters is the ones actually executed.
const ran = report.numTotalTests - (report.numPendingTests ?? 0);

if (ran === 0) {
  process.stderr.write(`selector matched no test: ${selector}\n`);
  process.exit(1);
}

process.exit(runFailed || report.numFailedTests > 0 ? 1 : 0);

import Ajv from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

const AjvClass = Ajv as unknown as typeof Ajv & {default: typeof Ajv};
const AjvConstructor = AjvClass.default || AjvClass;

const ajv = new AjvConstructor({
  strict: false,
  validateFormats: false,
  coerceTypes: false,
  useDefaults: false,
} as Record<string, boolean>);

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly compiledSchemas = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private getValidator(definition: ToolDefinition): ValidateFunction {
    const schema = definition.inputSchema;
    if (!schema) {
      return (() => true) as unknown as ValidateFunction;
    }
    let validator = this.compiledSchemas.get(schema);
    if (!validator) {
      try {
        validator = ajv.compile(schema);
      } catch (err) {
        throw new Error(
          `Invalid inputSchema for tool ${definition.name}: ${err instanceof Error ? err.message : String(err)}`,
          {cause: err}
        );
      }
      this.compiledSchemas.set(schema, validator);
    }
    return validator;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const toolInfo: StoredTool = {definitionSource: definition, execute};
    if (typeof definition !== 'function') {
      toolInfo.validator = this.getValidator(resolved);
    }
    this.tools.set(resolved.name, toolInfo);
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  // Executes a tool if input matches its schema (see [specs/hal-engine-tool-input-validation/spec.md]).
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }

    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = tool.validator ?? this.getValidator(definition);

    if (!validator(input)) {
      const errorMsg = ajv.errorsText(validator.errors, {dataVar: 'input'});
      const errors = validator.errors || [];
      const paths = errors
        .map(e => {
          const p = e.params as unknown as Record<string, string>;
          const err = e as typeof e & {instancePath?: string; dataPath?: string};
          const basePath = err.instancePath || err.dataPath;
          const path = basePath || p.missingProperty || 'root';
          return path;
        })
        .join(', ');

      log.warn('tool', 'invalid input', {name, paths});
      return {result: `Invalid input for tool ${name}: ${errorMsg}`};
    }

    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

